using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;
namespace BeamScheduleFormatter {
// Reuses the existing live settings controls and their persistence/change handlers.
partial class ProgramOfWorksForm {
 void RefineRCStart(){
  var page=tabs.TabPages.Cast<TabPage>().Single(p=>p.Text=="Reinforced Concrete Start");var start=page.Controls.OfType<FlowLayoutPanel>().Single();
  var original=start.Controls.OfType<PowCard>().Single();var memberButtons=original.Controls.OfType<FlowLayoutPanel>().Single().Controls.OfType<Button>().ToList();memberButtons.AddRange(start.Controls.OfType<Button>());
  var coverFields=rcCovers.Values.Select(c=>c.Parent).Distinct().ToList();var defaults=rcDefaultsStatus.Parent;var supply=new TableLayoutPanel{AutoSize=true,ColumnCount=2,RowCount=4,Margin=Padding.Empty,Padding=Padding.Empty};supply.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));supply.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));
  for(int i=0;i<ConcreteGroups.Length;i++){var box=readyMixGroups[ConcreteGroups[i]];box.AutoSize=true;box.MinimumSize=new Size(0,38);box.Margin=new Padding(4,4,18,4);supply.Controls.Add(box,i%2,i/2);if(i%2==0)supply.RowStyles.Add(new RowStyle(SizeType.AutoSize));}
  start.SuspendLayout();try{start.Controls.Clear();start.Padding=new Padding(20,16,20,20);start.WrapContents=false;start.FlowDirection=FlowDirection.TopDown;
   var title=new Label{Text="Reinforced concrete settings",AutoSize=true,Font=new Font("Segoe UI Semibold",19),Margin=new Padding(0,0,0,4)};start.Controls.Add(title);start.Controls.Add(new Label{Text="Set project defaults here. Member-specific details and commercial lengths are in each member's settings.",AutoSize=true,Margin=new Padding(0,0,0,16)});
   var actions=new FlowLayoutPanel{AutoSize=true,WrapContents=true,Margin=Padding.Empty,Padding=Padding.Empty};foreach(var button in memberButtons){button.MinimumSize=new Size(150,36);button.Margin=new Padding(0,0,10,8);actions.Controls.Add(button);}start.Controls.Add(new RCSettingsCard("Member settings","Materials, reinforcement and commercial lengths",actions));
   var covers=new FlowLayoutPanel{AutoSize=true,WrapContents=true,Margin=Padding.Empty};foreach(var field in coverFields){field.Width=152;field.Height=68;field.Margin=new Padding(0,0,14,8);foreach(Control c in field.Controls){c.Width=c is NumericUpDown?128:148;}covers.Controls.Add(field);}var lean=new FlowLayoutPanel{Width=162,Height=68,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=new Padding(0,0,0,8)};lean.Controls.Add(new Label{Text="Lean concrete (mm)",Width=156,Height=24});leanThickness.Width=128;lean.Controls.Add(leanThickness);covers.Controls.Add(lean);
   var coverBody=new FlowLayoutPanel{AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=Padding.Empty};coverBody.Controls.Add(covers);coverBody.Controls.Add(defaults);rcDefaultsStatus.MaximumSize=new Size(620,0);rcDefaultsStatus.Font=new Font("Segoe UI",9);start.Controls.Add(new RCSettingsCard("Cover and foundation defaults","Millimetres · save once for future projects",coverBody));
   start.Controls.Add(new RCSettingsCard("Concrete supply","Check Ready Mix for the corresponding member group. Unchecked groups use ordinary mix.",supply));
   bool resizing=false;Action resize=()=>{if(resizing||start.IsDisposed)return;resizing=true;try{int width=Math.Max(520,Math.Min(1240,start.ClientSize.Width-start.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth-4));foreach(var card in start.Controls.OfType<RCSettingsCard>()){card.Width=width;card.Arrange();}foreach(var label in start.Controls.OfType<Label>())label.MaximumSize=new Size(width,0);int bodyWidth=width-36;actions.MaximumSize=new Size(bodyWidth,0);covers.MaximumSize=new Size(bodyWidth,0);coverBody.MaximumSize=new Size(bodyWidth,0);defaults.MaximumSize=new Size(bodyWidth,0);supply.Width=bodyWidth;foreach(CheckBox box in supply.Controls)box.MaximumSize=new Size(Math.Max(200,bodyWidth/2-32),0);foreach(var card in start.Controls.OfType<RCSettingsCard>())card.Arrange();}finally{resizing=false;}};start.Resize+=(s,e)=>resize();Shown+=(s,e)=>resize();resize();
  }finally{start.ResumeLayout(true);}
 }
}
class RCSettingsCard:PowCard {
 readonly Label heading,description;readonly Control body;bool arranging;
 public RCSettingsCard(string title,string detail,Control content){heading=new Label{Text=title,AutoSize=true,Font=new Font("Segoe UI Semibold",12),Margin=Padding.Empty};description=new Label{Text=detail,AutoSize=true,ForeColor=PowTheme.Muted};body=content;Padding=new Padding(18);Margin=new Padding(0,0,0,14);Controls.Add(body);Controls.Add(description);Controls.Add(heading);body.SizeChanged+=(s,e)=>Arrange();SizeChanged+=(s,e)=>Arrange();}
 public void Arrange(){if(arranging||IsDisposed)return;arranging=true;try{int width=Math.Max(200,ClientSize.Width-Padding.Horizontal);heading.Location=new Point(Padding.Left,Padding.Top);heading.MaximumSize=new Size(width,0);description.Location=new Point(Padding.Left,heading.Bottom+5);description.MaximumSize=new Size(width,0);body.Location=new Point(Padding.Left,description.Bottom+14);body.Width=width;body.MaximumSize=new Size(width,0);body.PerformLayout();Height=body.Bottom+Padding.Bottom;}finally{arranging=false;}}
}
}
